create or replace function private.qa_operation_report() returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb:=private.qa_context();result jsonb;
begin
if coalesce(ctx->>'role','') not in ('admin','supervisor') then raise exception 'SUPERVISOR_REQUIRED' using errcode='42501';end if;
with base as (select r.*,a.name as analyst_name from private.qa_reviews r left join private.qa_analysts a on a.id=r.analyst_id), totals as (
select count(*) as selected,count(*) filter(where analyst_id is not null) as assigned,count(*) filter(where status='completed') as completed,count(*) filter(where status='pending') as pending,count(*) filter(where status='in_progress') as in_progress,count(*) filter(where verdict='errors' and status='completed') as errors,count(*) filter(where verdict='not_evaluable' and status='completed') as not_evaluable,count(distinct (completed_at at time zone 'America/Bogota')::date) filter(where status='completed') as active_days,avg(extract(epoch from completed_at-started_at)) filter(where status='completed') as mean_seconds,count(*) filter(where status='completed' and (completed_at at time zone 'America/Bogota')::date=day) as on_time,min(day) as first_day,max(day) as last_day from base)
select jsonb_build_object('stats',(select to_jsonb(t)||jsonb_build_object('daily_average',case when active_days>0 then completed::numeric/active_days end) from totals t),
'analysts',(select coalesce(jsonb_agg(x order by x.completed desc),'[]') from (select analyst_id,coalesce(analyst_name,'Sin asignar') name,string_agg(distinct country,' / ' order by country) countries,count(*) assigned,count(*) filter(where status='completed') completed,count(*) filter(where status='in_progress') in_progress,count(*) filter(where status='pending') pending,count(*) filter(where status='completed' and verdict='errors') errors,count(distinct (completed_at at time zone 'America/Bogota')::date) filter(where status='completed') active_days,avg(extract(epoch from completed_at-started_at)) filter(where status='completed') mean_seconds from base group by analyst_id,analyst_name) x),
'countries',(select coalesce(jsonb_agg(x order by x.completed desc),'[]') from (select coalesce(nullif(country,''),'Sin país') country,count(*) selected,count(*) filter(where status='completed') completed,count(*) filter(where status='completed' and verdict='errors') errors,count(*) filter(where status<>'completed') pending from base group by country) x),
'studies',(select coalesce(jsonb_agg(x order by x.study),'[]') from (select study,count(*) selected,count(*) filter(where status='completed') completed,count(*) filter(where status='completed' and verdict='errors') errors,count(*) filter(where status<>'completed') pending from base group by study) x),
'daily',(select coalesce(jsonb_agg(x order by x.day),'[]') from (select (completed_at at time zone 'America/Bogota')::date as day,count(*) completed,count(*) filter(where verdict='errors') errors from base where status='completed' group by 1) x),
'errors',(select coalesce(jsonb_agg(x order by x.errors desc),'[]') from (select k.key as kpi,count(*) as reviewed,count(*) filter(where k.value->>'evaluation'='incorrect') errors from base b cross join lateral jsonb_each(b.review_results) k where b.status='completed' group by k.key having count(*) filter(where k.value->>'evaluation'='incorrect')>0) x)
) into result;return result;end;$$;
revoke all on function private.qa_operation_report() from public,anon,authenticated;
do $$declare s text;begin select pg_get_functiondef('private.qa_api(text,jsonb)'::regprocedure) into s;if strpos(s,'operation_report()')=0 then s:=replace(s,$n$v_role:=ctx->>'role';$n$,$r$v_role:=ctx->>'role';if p_action='operation_report' then return private.qa_operation_report();end if;$r$);execute s;end if;end;$$;
create or replace function private.pqr_operation_report() returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb:=private.pqr_context();result jsonb;
begin
if coalesce(ctx->>'role','') not in ('admin','supervisor') then raise exception 'SUPERVISOR_REQUIRED' using errcode='42501';end if;
with base as (select r.*,a.name as analyst_name from private.pqr_active_reviews r left join private.pqr_analysts a on a.id=r.analyst_id), totals as (
select count(*) as selected,count(*) filter(where analyst_id is not null) as assigned,count(*) filter(where status='completed') as completed,count(*) filter(where status='pending') as pending,count(*) filter(where status='in_progress') as in_progress,count(*) filter(where verdict='errors' and status='completed') as errors,count(*) filter(where verdict='not_evaluable' and status='completed') as not_evaluable,count(distinct (completed_at at time zone 'America/Bogota')::date) filter(where status='completed') as active_days,avg(extract(epoch from completed_at-started_at)) filter(where status='completed') as mean_seconds,count(*) filter(where status='completed' and (completed_at at time zone 'America/Bogota')::date=day) as on_time,min(day) as first_day,max(day) as last_day from base)
select jsonb_build_object('stats',(select to_jsonb(t)||jsonb_build_object('daily_average',case when active_days>0 then completed::numeric/active_days end) from totals t),
'analysts',(select coalesce(jsonb_agg(x order by x.completed desc),'[]') from (select analyst_id,coalesce(analyst_name,'Sin asignar') name,string_agg(distinct country,' / ' order by country) countries,count(*) assigned,count(*) filter(where status='completed') completed,count(*) filter(where status='in_progress') in_progress,count(*) filter(where status='pending') pending,count(*) filter(where status='completed' and verdict='errors') errors,count(distinct (completed_at at time zone 'America/Bogota')::date) filter(where status='completed') active_days,avg(extract(epoch from completed_at-started_at)) filter(where status='completed') mean_seconds from base group by analyst_id,analyst_name) x),
'countries',(select coalesce(jsonb_agg(x order by x.completed desc),'[]') from (select coalesce(nullif(country,''),'Sin país') country,count(*) selected,count(*) filter(where status='completed') completed,count(*) filter(where status='completed' and verdict='errors') errors,count(*) filter(where status<>'completed') pending from base group by country) x),
'studies',(select coalesce(jsonb_agg(x order by x.study),'[]') from (select study,count(*) selected,count(*) filter(where status='completed') completed,count(*) filter(where status='completed' and verdict='errors') errors,count(*) filter(where status<>'completed') pending from base group by study) x),
'daily',(select coalesce(jsonb_agg(x order by x.day),'[]') from (select (completed_at at time zone 'America/Bogota')::date as day,count(*) completed,count(*) filter(where verdict='errors') errors from base where status='completed' group by 1) x),
'errors',(select coalesce(jsonb_agg(x order by x.errors desc),'[]') from (select k.key as kpi,count(*) as reviewed,count(*) filter(where k.value->>'evaluation'='incorrect') errors from base b cross join lateral jsonb_each(b.review_results) k where b.status='completed' group by k.key having count(*) filter(where k.value->>'evaluation'='incorrect')>0) x)
) into result;return result;end;$$;
revoke all on function private.pqr_operation_report() from public,anon,authenticated;
do $$declare s text;begin select pg_get_functiondef('private.pqr_api(text,jsonb)'::regprocedure) into s;if strpos(s,'operation_report()')=0 then s:=replace(s,$n$v_role:=ctx->>'role';$n$,$r$v_role:=ctx->>'role';if p_action='operation_report' then return private.pqr_operation_report();end if;$r$);execute s;end if;end;$$;

